#include <iostream>
#include <vector>
#include <string>
using namespace std;

// 处理一组测试数据，返回最终字符串
string transformString(const string& s, const vector<pair<char, char>>& ops) {
    // mp[i] 表示原字符 ('a' + i) 最终会变成什么字符
    vector<char> mp(26);
    for (int i = 0; i < 26; i++) {
        mp[i] = 'a' + i;
    }

    // 依次处理替换操作
    for (auto& op : ops) {
        char x = op.first;
        char y = op.second;

        // 所有当前映射为 x 的字符都改成 y
        for (int i = 0; i < 26; i++) {
            if (mp[i] == x) {
                mp[i] = y;
            }
        }
    }

    // 根据最终映射生成答案
    string res = s;
    for (int i = 0; i < (int)res.size(); i++) {
        res[i] = mp[res[i] - 'a'];
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, q;
        cin >> n >> q;

        string s;
        cin >> s;

        vector<pair<char, char>> ops;
        ops.reserve(q);

        for (int i = 0; i < q; i++) {
            char x, y;
            cin >> x >> y;
            ops.push_back({x, y});
        }

        cout << transformString(s, ops) << '\n';
    }

    return 0;
}
